const objeto = {
  nome: 'Ana',
  // função comum: this = quem chamou (o objeto)
  apresentar: function () {
    return `Eu sou ${this.nome}`;
  },
  // arrow: this = o de fora do objeto (no módulo, undefined)
  apresentarArrow: () => `Eu sou ${this.nome}`,
  // arrow DENTRO de método comum: herda o this do método
  contar: function () {
    const somar = () => this.nome.length; // this = objeto
    return somar();
  },
};

console.log(objeto.apresentar());    // Eu sou Ana
// objeto.apresentarArrow();          // ERRO: this é undefined fora
console.log(objeto.contar());        // 3 (comprimento de 'Ana')

const tarefas = [
  { titulo: 'Estudar closures', concluida: true },
  { titulo: 'Praticar arrow', concluida: false },
  { titulo: 'Revisar escopo', concluida: true },
];

// Passos 1 e 2: arrow com retorno implícito em map e filter.
const titulos = tarefas.map(t => t.titulo);
const concluidas = tarefas.filter(t => t.concluida);

// Passo 3: método comum — precisa do próprio this.
const quadro = {
  tarefas,
  resumo: function () {
    // Passo 4: arrow dentro do método herda o this do método.
    const concluidas = this.tarefas.filter(t => t.concluida);
    const taxa = concluidas.length / this.tarefas.length;
    return `${concluidas.length} de ${this.tarefas.length} (${taxa * 100}%)`;
  },
};

// Passo 5: confira.
console.log(titulos);              // ['Estudar closures', 'Praticar arrow', 'Revisar escopo']
console.log(concluidas.length);    // 2
console.log(quadro.resumo());      // 2 de 3 (66.666...%)
